INSERT INTO `w_bo_xs_projectmanage` VALUES ('2062712627808645121', '0', '0', '1638968357988946', '何家文', '2026-06-05 09:46:28', '1638968357988946', '何家文', '2026-06-05 09:47:08', '1', '2062712628001533954', 'SUCCESS_END', '成功结束', '1055369916', '日化2组（南区）', '2', 'XMBM202606050006', '1', '明确需求', '戈海  DH-A33845--JKB2490AJK 香格里拉 优化调整', '1984130167739404290', '广州戈海贸易有限公司', '型号：DH-A33845--JKB2490AJK 香格里拉\n背景：DH-A33845--JKB2490AJK这款香精现客户用于洗护沐和喷雾产品，但测试下来有两个产品不是很好理想\n需求一：客户沐浴露，沐浴露的基体是表活，添加量1.2%，要出口到中东市场。反馈产品香气还是淡，需要帮忙继续加强香气。\n需求二：喷雾产品 添加香精后，后调出现发酸的情况，麻烦按照客户配方帮忙再优化一下。\n喷雾的配方：水、PEG-40氢化蓖麻油、甘油、香精、苯氧乙醇、羟苯甲酯、乙基己基甘油、乙二胺四乙酸二钠、丁二醇、甲基二异丙基丙酰胺、聚山梨酯20', '1', '3', 'B级项目', '1638968357988946', '何家文', '16455177663846080', '常晓爽', NULL, NULL, NULL, NULL, NULL, '0', '否', '', '', NULL, NULL, NULL, '0', '否', '', '', NULL, '', '', '', '', '', '', '', '', NULL, NULL, NULL, NULL, '2027-06-06 00:00:00', '120元左右', NULL, NULL, NULL, NULL, NULL);
