INSERT INTO `w_bo_xs_projectmanage` VALUES ('2062757991509078017', '0', '0', '16466317325076496', '梁皓', '2026-06-05 12:46:44', '16466317325076496', '梁皓', '2026-06-05 12:46:44', '1', '2062757991701966850', 'SUCCESS_END', '成功结束', '57435696', '香氛销售部', '1', 'XMBM202606050015', '1', '明确需求', '不蟹--海洋木质调推荐20260605', '2053026083887865858', '上海不蟹科技有限公司', '高尚领域--韩\n此为客户Brief\n前调是清冽的柠檬马鞭草和微咸的海盐，像那阵穿透蓝调时刻的凉风，唤醒空气的湿润质地。\n中调是核心的蓝色氛围——薰衣草带来金属般清冷的光泽，紫罗兰贡献粉质的花香和微甜绿意，再以鸢尾的泥土感和木质调支撑结构，仿佛凝视那片渐深的蓝色天幕。\n后调是归于平静的柔软：白麝香包裹一切，留下洁净的肌肤感；雪松提供干燥木质的骨架；零陵香豆则透出一点琥珀色的暖意——提醒你，蓝调之后，灯火将起。\n推荐带有蓝色联想的香气\n需要海洋木质调\n另需要LYP1050ALY 类似蓝风铃气味的推荐\n应用品类喷雾 蜡烛 香包 香卡\n需要选择有库存的样品\n需求价格500\n需求时间：6.8寄出', '1', '4', 'C级项目', '113845370124130976,16466317325076496', '彭佳庆,梁皓', '17253690046572896', '周宇', NULL, NULL, NULL, NULL, NULL, '0', '否', '', '', NULL, NULL, NULL, '0', '否', '', '', NULL, '', '', '2', '无要求', '', '', '2,3,4', 'IFRA,SDS,COA', NULL, NULL, '客户确样后提供，需要81过敏原', NULL, '2027-06-30 00:00:00', '500', NULL, NULL, NULL, NULL, NULL);
