INSERT INTO `w_bo_xs_projectmanage` VALUES ('2064889277090615297', '0', '0', '050363634136321790', '逯柏松', '2026-06-11 09:55:42', '050363634136321790', '逯柏松', '2026-06-11 09:55:42', '1', '2064889277195468802', 'SUCCESS_END', '成功结束', '57435696', '香氛销售部', '1', 'XMBM202606110004', '1', '明确需求', '忍冬复方精油仿香-逐本', '1984130169849139201', '杭州舒彩网络科技有限公司', '价格：不超过450元\n加香量：不超过1%，\n时间：6月18前寄出\n\nBRF\n香气定位\n以忍冬花为灵感，打造具有东方气质的金色花木香调。\n整体传递：\n温润、柔和、高级、修护感、层次丰富。\n核心要求\n东方花香主体\n以忍冬花构建核心花香；\n呈现柔和、清润、温暖的花香气质；\n不偏药感、草本感。\n修护联想\n闻起来有滋养、顺滑、柔润感；\n与护发精油的修护功效形成关联。\n高级层次感\n前中后调过渡自然；\n花香丰富但不甜腻；\n留香舒适且有记忆点。\n\n复方成分由高到低排列：\n忍冬\n葡萄柚\n晚香玉\n白兰花\n弗吉尼亚雪松\n佛手柑\n粉红胡椒\n乳香\n广藿香\n丁香\n\n寄样地址：\n李玲\n17370737282\n浙江省杭州市萧山区协和辉丰大厦A座2503', '5', '1', 'S级项目', '113845370124130976,050363634136321790', '彭佳庆,逯柏松', '17253690046572896', '周宇', NULL, NULL, NULL, NULL, NULL, '0', '否', '', '', NULL, NULL, NULL, '0', '否', '', '', NULL, '', '', '', '', '', '', '', '', NULL, NULL, NULL, NULL, '2026-09-30 00:00:00', '450', NULL, NULL, NULL, NULL, NULL);
