INSERT INTO `w_bo_xs_projectmanage` VALUES ('2066451756388175873', '0', '0', '1638968357988946', '何家文', '2026-06-15 17:24:26', '1638968357988946', '何家文', '2026-06-15 17:24:26', '1', '2066451756572721154', 'SUCCESS_END', '成功结束', '1055369916', '日化2组（南区）', '1', 'XMBM202606150027', '1', '明确需求', '方生  LYP2210ALY--DH-Z111174	咖啡	留香加强', '2059623163884429313', '香水博主  方生', '型号：LYP2210ALY--DH-Z111174	咖啡	\n需求：客户反馈目前的甜度非常合适，就是整体留香不太好，希望能加强一下留香的效果，但不要加强整体的甜度\n产品：香水\n价格：无要求', '1', '4', 'C级项目', '1638968357988946', '何家文', '16825006662777257', '齐钰', NULL, NULL, NULL, NULL, NULL, '0', '否', '', '', NULL, NULL, NULL, '0', '否', '', '', NULL, '', '', '', '', '', '', '', '', NULL, NULL, NULL, NULL, '2027-06-06 00:00:00', '无要求', NULL, NULL, NULL, NULL, NULL);
INSERT INTO `w_bo_xs_projectmanage` VALUES ('2066455166567043073', '0', '0', '02461210300720808373', '余鹏程', '2026-06-15 17:37:59', '02461210300720808373', '余鹏程', '2026-06-15 17:37:59', '1', '2066455166755782658', 'SUCCESS_END', '成功结束', '57435696', '香氛销售部', '1', 'XMBM202606150029', '1', '明确需求', '（非常紧急）北京丽质华堂香精推荐26-06-15', '2066452550269259777', '北京丽质华堂化妆品有限公司', '【需求说明】\n香型要求：客户公司主打成分为紫檀木提取物，创始人亦有“紫檀女王”之称。因此希望该系列护肤品能呈现明显且高级的檀香气息，以呼应产品定位。\n香精类型：可为普通香精或复配精油形式。\n目标人群：25–35岁轻熟龄女性。\n产品功效：主打敏感肌抗初老。\n肤感与安全要求：需温和无刺激，符合护肤品添加标准，不影响产品稳定性与安全性。\n\n【推荐逻辑】\n方向一：请推荐是市面上比较高端的沉檀香型（包括商业香和沙龙香）2~4款\n方向二：我司原创的古方复刻香型2~4款，需寄原版（标签标注清楚，跟性价版区分开），同时可做适当降价处理，注意天然油的含量比例\n\n【加香要求】\n用于所有剂型，包括洁面水乳精华面霜身体乳等；\n客户会寄来一点面霜基料，同时评香可根据我司目前可制作的加香小样种类，酌情安排其他类型产品的加香；\n加香量万分之2~5之间，价位控制在8w以内；\n需将香精和加香小样一并寄出，并出具送样清单', '10', '1', 'S级项目', '02461210300720808373', '余鹏程', '16455177663846080', '常晓爽', NULL, NULL, NULL, NULL, NULL, '1', '是', '', '', NULL, NULL, NULL, '0', '否', '', '', NULL, '', '', '1', '不含过敏原', '4', '中国化妆品INCI', '', '', NULL, NULL, NULL, NULL, '2027-06-15 00:00:00', '80000', NULL, NULL, NULL, NULL, NULL);
