INSERT INTO `w_bo_xs_projectmanage` VALUES ('2071840145887186945', '0', '0', '16466317325076496', '梁皓', '2026-06-30 14:15:58', '16466317325076496', '梁皓', '2026-06-30 14:15:58', '1', '2071840146151424001', 'SUCCESS_END', '成功结束', '57435696', '香氛销售部', '1', 'XMBM202606300013', '1', '明确需求', '挚物志--百香果、苹果、薰衣草水性喷雾修改20260630', '1984130169874305027', '上海伽罗商务咨询有限公司', '寄：上海市闵行区中春路7001号明谷科技园A栋511 夏甦 13817346604\n应客户需求做透明水质香精\nLYA2362ALY	爆汁百香果（透明水质）\nLYP1355BLY	青苹果乐园（透明水质）\nLYP1181CLY	真正薰衣草（透明水质）\n需求价格200以内\n需求时间：7.7\n需要5%水性喷雾样品', '1', '4', 'C级项目', '113845370124130976,16466317325076496', '彭佳庆,梁皓', '17253690046572896', '周宇', NULL, NULL, NULL, NULL, NULL, '0', '否', '', '', NULL, NULL, NULL, '0', '否', '', '', NULL, '', '', '2', '无要求', '5', '普通日化', '2,3,4', 'IFRA,SDS,COA', NULL, NULL, '客户确样后申请', NULL, '2027-07-11 00:00:00', '200以内', NULL, NULL, NULL, NULL, NULL);
INSERT INTO `w_bo_xs_projectmanage` VALUES ('2071845677503074305', '0', '0', '16466317325076496', '梁皓', '2026-06-30 14:37:57', '16466317325076496', '梁皓', '2026-06-30 14:37:57', '1', '2071845677662453761', 'SUCCESS_END', '成功结束', '57435696', '香氛销售部', '1', 'XMBM202606300014', '1', '明确需求', '挚物志--果香、茶香香水创香20260630', '1984130169874305027', '上海伽罗商务咨询有限公司', '寄样地址：上海市闵行区中春路7001号明谷科技园A栋511 夏甦 13817346604\n\n注意！该项目有两个创香需求！！！！！！！\n\n需求1：客户果香类香水创香\n客户会提供浴见-醒山桃市场样品需要该类型感受的果香香水创香\n具体水果类型可在客户样品提供后确定\n需求价格：350元\n需求时间：暂定7.15（主要看实际香氛的质感）\n需要15%香水加香产品\n\n需求2：茶类香水创香\n该创香为高定线香水，会有出口欧美市场需求，需确认法规！！！！！！！！！\n客户需要小青柑以及滇红茶香香水创香\n先做小青柑以下为小青柑创香思路\n需要有中式感以及香水的层次感以及需要一小部分的大众接受度愉悦度\nLYP1495ALY or LYA2138ALY or LYP1492ALY\n可加重红茶感与青绿感需要体现出中式香氛情节与青绿自然的联结感\n需求价格：650以内\n需求时间：暂定7.17（主要看实际香氛的质感）\n需要15%香水加香产品', '3', '2', 'A级项目', '113845370124130976,16466317325076496', '彭佳庆,梁皓', '17253690046572896', '周宇', NULL, NULL, NULL, NULL, NULL, '0', '否', '', '', NULL, NULL, NULL, '0', '否', '', '', NULL, '', '', '2', '无要求', '4', '中国化妆品INCI', '2,3,4', 'IFRA,SDS,COA', NULL, NULL, '客户产品用于香水有出口需求需注意，确样后提供', NULL, '2027-06-30 00:00:00', '350~650', NULL, NULL, NULL, NULL, NULL);
INSERT INTO `w_bo_xs_projectmanage` VALUES ('2071869051604291585', '0', '0', '16466317325076496', '梁皓', '2026-06-30 16:10:50', '16466317325076496', '梁皓', '2026-06-30 16:10:50', '1', '2071869051847557121', 'SUCCESS_END', '成功结束', '57435696', '香氛销售部', '1', 'XMBM202606300016', '1', '明确需求', '湖北申泰--芦荟、万寿菊产品升级20260630', '1984130173452046338', '湖北申泰医疗用品有限公司', '不需要寄样\n需求紧急！！！！！！！\n万寿菊（水质）LYP1082ALY \n芦荟（水质）LYP1081ALY\n客户产品使用在婴儿湿巾产品内\n添加量0.1%\n目前桂醛与芳樟醇超出欧标婴儿湿巾用品限用范围需要优化升级该产品\n需求价格：\n芦荟售价：87元\n万寿菊售价：117元\n优化升级版需在该价格内\n需求时间：7.1（需求紧急）', '1', '4', 'C级项目', '113845370124130976,16466317325076496', '彭佳庆,梁皓', '17253690046572896', '周宇', NULL, NULL, NULL, NULL, NULL, '0', '否', '', '', NULL, NULL, NULL, '0', '否', '', '', NULL, '', '', '', '', '', '', '', '', NULL, NULL, '需要81过敏原', NULL, '2027-06-30 00:00:00', '87&117', NULL, NULL, NULL, NULL, NULL);
INSERT INTO `w_bo_xs_projectmanage` VALUES ('2071888721757589506', '0', '0', '113845370124130976', '彭佳庆', '2026-06-30 17:29:00', '113845370124130976', '彭佳庆', '2026-06-30 17:29:00', '1', '2071888721950523394', 'SUCCESS_END', '成功结束', '73351495', '总经办', '1', 'XMBM202606300017', '1', '明确需求', '西屿茉莉无火+洗护（重要）推荐', '2058744456831524866', '浙江西屿智能科技有限公司', '西屿茉莉无火+洗护（重要）：\nLYP703ALY（需要改无火版+洗护版）和LYA1597GLY（无火版）DH160220E(洗护版）要求有爆香香基和留香香基还有广西横州小花茉莉天然油添加\n价格：无火200以内，洗护400以内\n香精：10ml\n时间:7月10号前寄出\n备注：无火加香成品打签10%，实际加香12%；洗护加香成品打签1.5%，实际加香2%\n香精和加香成品一起寄出\n寄bella', '5', '1', 'S级项目', '113845370124130976,050363634136321790', '彭佳庆,逯柏松', '17253690046572896', '周宇', NULL, NULL, NULL, NULL, NULL, '0', '否', '', '', NULL, NULL, NULL, '0', '否', '', '', NULL, '', '', '', '', '', '', '', '', NULL, NULL, NULL, NULL, '2026-12-31 00:00:00', '200--400', NULL, NULL, NULL, NULL, NULL);
INSERT INTO `w_bo_xs_projectmanage` VALUES ('2071977787194855426', '0', '0', '1638968357988946', '何家文', '2026-06-30 23:22:55', '1638968357988946', '何家文', '2026-06-30 23:22:55', '1', '2071977787459092481', 'SUCCESS_END', '成功结束', '1055369916', '日化2组（南区）', '1', 'XMBM202606300018', '1', '明确需求', '嘉丹婷   洗护香型新品推荐', '1984130172143423489', '广东嘉丹婷日用品有限公司', '（1）价格：限制在180元/1kg \n（2）添加量：预计0.4~0.6% \n（3）香型需求：不要找纯果香，纯木质香，要复合型花香型的，必须要有花香调；要爆一点愉悦度高的香型。\n（4）应用产品：澳雪精油香氛系列。前期先落地控油/柔顺洗发水各1款、2款沐浴露、1款发膜（与柔顺洗发水共用香型）；后续考虑延伸至身体乳、手霜。\nPS:寄来4款客户目前内部入选的香型，其中柚见雪松是嘉丹婷老板目前最喜欢的，可供参考，但不要推荐跟这4款风格一样的香型，避免重叠。寄出前需要和王鑫确认没问题再寄出。', '1', '3', 'B级项目', '1638968357988946,0549274114954944', '何家文,王鑫', '16455177663846080', '常晓爽', '[{\"fileName\":\"微信图片_20260630232055_105_102.jpg\",\"timestamp\":\"0Nlr03vVwamrMr0kk8Id\",\"size\":3194048,\"secret\":null,\"fileId\":\"d3f4be6c-0531-4743-b31e-341df2c1a86b\",\"showSize\":\"3.0M\",\"fileClass\":\"iconBox imageBox\"}]', NULL, NULL, NULL, NULL, '1', '是', '', '', NULL, NULL, NULL, '1', '是', '', '', NULL, '', '', '', '', '', '', '', '', NULL, NULL, NULL, NULL, '2027-06-30 00:00:00', '180元/1kg', NULL, NULL, NULL, NULL, NULL);
