INSERT INTO `w_bo_xs_projectmanage` VALUES ('2072221931406348290', '0', '0', '16466317325076496', '梁皓', '2026-07-01 15:33:03', '16466317325076496', '梁皓', '2026-07-01 15:33:03', '1', '2072221931603476482', 'SUCCESS_END', '成功结束', '57435696', '香氛销售部', '1', 'XMBM202607010016', '1', '明确需求', 'Yili--山下有松--桂花乌龙沉香香水修改20260701', '2048618830288084993', 'Yili制香', '寄北京市朝阳区浩华文创园C9songmont 王妍 13581841518\n根据客户寄样香精先给客户做25%和20%两个浓度的香水加香产品，做3~5g的香水成品\n取部分香精进GC分析谱图与仿香标样，剩余需寄回给客户\n目前该版本不是最终确认版本Yili会有新的优化版本，此为山下有松第3支香水\n客户目前感觉香气有些甜需要减甜增加桂花花韵，需求有两个方向优化版\n需求1：减甜增桂花，做增加茶感方向\n需求2：减甜增桂花，做增加檀香木方向\n（暂未需要我们先做调整，有该需求可能）\n山下有松品牌方老板喜欢精油感的香气可参考黎明香根草的感觉\n整体香气是桂花+乌龙+沉香+木质\n后续定版后会由我司仿香做成品出货\n需求价格：暂无（预计10000元/kg）\n需求加香量20% 25%两个\n产品用于香水内\n目前该工单为后续项目做准备以及给客户提供加香产品用', '10', '1', 'S级项目', '113845370124130976,16466317325076496', '彭佳庆,梁皓', '16455177663846080', '常晓爽', NULL, NULL, NULL, NULL, NULL, '0', '否', '', '', NULL, NULL, NULL, '0', '否', '', '', NULL, '', '', '2', '无要求', '4', '中国化妆品INCI', '2,3,4', 'IFRA,SDS,COA', NULL, NULL, '产品用于香水加香量25%，客户确认后提供，会有出口需求', NULL, '2028-07-31 00:00:00', '10000', NULL, NULL, NULL, NULL, NULL);
