INSERT INTO `w_bo_xs_projectmanage` VALUES ('2077247484194705410', '0', '0', '02461210300720808373', '余鹏程', '2026-07-15 12:22:48', '02461210300720808373', '余鹏程', '2026-07-15 12:22:48', '1', '2077247484484108290', 'SUCCESS_END', '成功结束', '57435696', '香氛销售部', '1', 'XMBM202607150013', '1', '明确需求', '成都优易仿香项目26-07-15', '1984130168368549890', '成都优易香氛信息科技有限公司', '客户寄来四款标样仿香，要求尽量像，用于空间香氛\n其中，标样名称为“鼎盛-杨”和“上海-姚”这两个标样，最终成品请调香师重新命名', '5', '4', 'C级项目', '02461210300720808373', '余鹏程', '16275212368889684', '赵文雅', NULL, NULL, NULL, NULL, NULL, '0', '否', '', '', NULL, NULL, NULL, '0', '否', '', '', NULL, '', '', '', '', '', '', '', '', NULL, NULL, NULL, NULL, '2027-07-15 00:00:00', '150以内', NULL, NULL, NULL, NULL, NULL);
INSERT INTO `w_bo_xs_projectmanage` VALUES ('2077265788644872194', '0', '0', '17400514601408872', '于姗姗', '2026-07-15 13:35:32', '17400514601408872', '于姗姗', '2026-07-15 13:35:32', '1', '2077265788871360514', 'SUCCESS_END', '成功结束', '1009466484', '销售服务部', '1', 'XMBM202607150014', '1', '明确需求', '嘉美-推荐香精-20260715', '2059509849523183618', '广州市嘉美化妆品有限公司', '客户创香需求：\n魏紫 原生香气特征\n药感甜香 + 紫罗兰粉质 + 木质冷香，香气温润厚重、贵气成熟、辨识度极高。\n\n香水定位\n东方紫花香 EDP（晚宴高端线）\n•风格：端庄、成熟、贵气、神秘紫韵\n•人群：30 + 女性、晚宴、商务正式场合\n•季节：秋冬最佳，春秋微凉天气也很绝\n\n留香（15% 香精 EDP）\n•皮肤：9–11 小时（厚重留香）\n•衣物：13–17 小时（紫香 + 药感持久）\n•尾调：2–3 天（木质琥珀残留强）\n\n意境文案\n「魏紫・紫宸凝芳」\n紫为贵，沉为尊。\n千瓣凝霞，暗香沉郁，是宫廷深处的端庄，亦是岁月沉淀的从容华贵。\n\n调香配方思路\n•前调：紫罗兰叶、葡萄柚、丁香（冷润开场）\n•中调：魏紫牡丹、鸢尾、玫瑰（紫调粉质甜香）\n•尾调：广藿香、沉香、檀香、龙涎、麝香（厚重贵气底）\n用途香水\n各10克', '5', '4', 'C级项目', '17400514601408872,0549274114954944', '于姗姗,王鑫', '16825006662777257', '齐钰', NULL, NULL, NULL, NULL, NULL, '0', '否', '', '', NULL, NULL, NULL, '0', '否', '', '', NULL, '', '', '', '', '', '', '', '', NULL, NULL, NULL, NULL, '2027-07-15 00:00:00', '-', NULL, NULL, NULL, NULL, NULL);
