INSERT INTO `w_bo_xs_projectmanage` VALUES ('2079861597169225729', '0', '0', '16466317325076496', '梁皓', '2026-07-22 17:30:21', '16466317325076496', '梁皓', '2026-07-22 17:43:18', '1', '2079861597303406594', 'SUCCESS_END', '成功结束', '57435696', '香氛销售部', '2', 'XMBM202607220017', '1', '明确需求', '粉合--城市植萃系列推荐20260722', '2036286715231977474', '上海粉合化妆品有限公司', '销售自提\n需要推荐4款大牌大牌香氛\n需要香精内部添加的天然精油有治疗失眠、焦虑、肥胖等城市病需求的功效\n不用我们做任何宣传只需要内部加了类似功效的天然原料即可\n客户以次为卖点，只需每款有一个原料即可，需要四个不同的天然精油\n都市病：睡眠障碍、情绪焦躁、肥胖、抑郁等\n睡眠障碍：薰衣草、洋甘菊、岩兰草、佛手柑和檀香\n情绪焦躁：薰衣草\n促进代谢：薄荷、姜\n抑郁：玫瑰、香根草、依兰、薰衣草、佛手柑、罗勒、柠檬、乳香、洋甘菊、广藿香、鼠尾草、茉莉、薄荷、缬草根和天竺葵\n如有其他选择也可使用但需告知针对的都市病以及使用精油\n需求价格：350以内\n从上海库选样\n需求时间：7.29\n需要10%香水加香产品', '1', '4', 'C级项目', '113845370124130976,16466317325076496', '彭佳庆,梁皓', '17253690046572896', '周宇', NULL, NULL, NULL, NULL, NULL, '0', '否', '', '', NULL, NULL, NULL, '0', '否', '', '', NULL, '', '', '', '', '', '', '', '', NULL, NULL, NULL, NULL, '2027-07-31 00:00:00', '350以内', NULL, NULL, NULL, NULL, NULL);
